<template>
    <dialog ref="dialog" class="dialog" :class="dialogClasses" :aria-label="title || 'Dialoglodziņš'">
        <div class="dialog-header">
            <h5 v-if="title" class="dialog-title">{{ title }}</h5>
            <slot name="header" />
            <button type="button" class="btn-close" data-bs-dismiss="dialog" aria-label="Aizvērt"></button>
        </div>

        <div class="dialog-body">
            <slot />
        </div>

        <div v-if="$slots.footer" class="dialog-footer">
            <button v-if="footerClose" type="button" class="btn btn-link btn-danger" data-bs-dismiss="dialog">Aizvērt</button>
            <slot name="footer" />
        </div>
    </dialog>
</template>

<script>
import { shallowRef } from 'vue';

export default {
    name: 'Modal',
    emits: ['close'],
    props: {
        title: String,
        dialogClass: String,
        preventOutsideClick: Boolean,
        footerClose: { type: Boolean, default: true },
    },
    data() {
        return {
            dialogInstance: shallowRef(null),
            opener: null,
        };
    },
    computed: {
        dialogClasses() {
            return this.dialogClass
                ?.replace(/\bmodal-(sm|lg|xl|fullscreen)\b/g, 'dialog-$1')
                .replace(/\bmodal-dialog-scrollable\b/g, 'dialog-scrollable');
        },
    },
    mounted() {
        this.$refs.dialog.addEventListener('hidden.bs.dialog', this.handleClosed);
    },
    beforeUnmount() {
        this.$refs.dialog.removeEventListener('hidden.bs.dialog', this.handleClosed);
        this.dialogInstance?.dispose();
    },
    methods: {
        async show() {
            const dialog = this.$refs.dialog;
            const opener = document.activeElement;
            const { Dialog } = await import('bootstrap');

            if (this.$refs.dialog !== dialog || dialog.open) {
                return;
            }

            this.opener = opener;
            this.dialogInstance = Dialog.getOrCreateInstance(dialog, {
                backdrop: this.preventOutsideClick ? 'static' : true,
            });
            await this.dialogInstance.show(opener);
        },
        hide() {
            return this.dialogInstance?.hide();
        },
        handleClosed() {
            if (this.opener?.isConnected) {
                this.opener.focus({ preventScroll: true });
            }

            this.opener = null;
            this.$emit('close');
        },
    },
};
</script>
